import React, { useState } from 'react';
import { Outlet, NavLink } from 'react-router-dom';
import { useWeb3 } from '../context/Web3Context';
import { 
  HomeIcon, 
  CurrencyDollarIcon, 
  UserGroupIcon, 
  GiftIcon, 
  Bars3Icon, 
  XMarkIcon, 
  WalletIcon
} from '@heroicons/react/24/outline';
import glassToast from '../utils/toastUtils';

const Layout = () => {
  const { account, loading, isConnected, connectWallet, disconnectWallet, formatAddress } = useWeb3();
  const [sidebarOpen, setSidebarOpen] = useState(false);

  const toggleSidebar = () => {
    setSidebarOpen(!sidebarOpen);
  };

  const closeSidebar = () => {
    setSidebarOpen(false);
  };

  const navLinks = [
    { name: '仪表盘', path: '/', icon: <HomeIcon className="w-6 h-6" /> },
    { name: '质押', path: '/staking', icon: <CurrencyDollarIcon className="w-6 h-6" /> },
    { name: '推荐系统', path: '/referral', icon: <UserGroupIcon className="w-6 h-6" /> },
    { name: '奖励中心', path: '/rewards', icon: <GiftIcon className="w-6 h-6" /> },
  ];

  const handleConnectWallet = async () => {
    try {
      console.log('点击连接钱包按钮');
      if (isConnected) {
        console.log('当前已连接，执行断开操作');
        disconnectWallet();
      } else {
        console.log('当前未连接，执行连接操作');
        if (!window.ethereum) {
          glassToast.error('请安装MetaMask钱包!');
          return;
        }
        await connectWallet();
      }
    } catch (error) {
      console.error('钱包操作失败:', error);
      glassToast.error(error.message || '操作失败，请重试');
    }
  };

  return (
    <div className="min-h-screen gradient-background">
      {/* 移动端侧边栏 */}
      <div className={`fixed inset-0 z-40 lg:hidden ${sidebarOpen ? 'block' : 'hidden'}`}>
        <div className="fixed inset-0" onClick={closeSidebar}></div>
        <div className="fixed inset-y-0 left-0 flex flex-col z-40 max-w-xs w-full glass overflow-y-auto">
          <div className="flex items-center justify-between h-16 px-6">
            <span className="text-xl font-bold text-gold-700">ArriveOnTime</span>
            <button onClick={closeSidebar} className="rounded-md p-2 text-gray-800 hover:text-primary-500">
              <XMarkIcon className="w-6 h-6" />
            </button>
          </div>
          <nav className="flex-1 px-4 py-4 space-y-2">
            {navLinks.map((link) => (
              <NavLink
                key={link.path}
                to={link.path}
                className={({ isActive }) => 
                  `flex items-center px-4 py-3 rounded-lg transition-colors ${isActive 
                    ? 'bg-bluebrand-50 text-bluebrand-600 font-semibold border border-bluebrand-100' 
                    : 'hover:bg-bluebrand-50/60 text-bluebrand-700'}`
                }
                onClick={closeSidebar}
              >
                {link.icon}
                <span className="ml-3">{link.name}</span>
              </NavLink>
            ))}
          </nav>
        </div>
      </div>

      {/* 桌面端侧边栏 */}
      <div className="hidden lg:fixed lg:inset-y-0 lg:flex lg:flex-col lg:z-10 glass ml-6 mt-6 mb-6 rounded-xl w-48">
        <div className="flex items-center justify-center h-16 px-6 border-b border-black/10 bg-gradient-to-r from-gold-50 to-white">
          <span className="text-xl font-bold text-gold-700">ArriveOnTime</span>
        </div>
        <nav className="flex-1 px-4 py-6 space-y-3">
          {navLinks.map((link) => (
            <NavLink
              key={link.path}
              to={link.path}
              className={({ isActive }) => 
                `flex items-center px-4 py-3 transition-all rounded-lg ${isActive 
                  ? 'bg-bluebrand-50 text-bluebrand-600 font-medium' 
                  : 'hover:bg-bluebrand-50/60 text-bluebrand-700'}`
              }
            >
              {link.icon}
              <span className="ml-3">{link.name}</span>
            </NavLink>
          ))}
        </nav>
      </div>

      {/* 主要内容区域 */}
      <div className="lg:pl-72 pt-24">
        {/* 顶部导航栏 */}
        <header className="glass fixed top-0 left-1/2 transform -translate-x-1/2 z-[100] w-[calc(100vw-3rem)] max-w-4xl mx-auto mt-4 flex h-16 items-center justify-between rounded-xl px-4 shadow-lg">
          <button onClick={toggleSidebar} className="lg:hidden p-2 rounded-md text-gray-800 hover:text-primary-500">
            <Bars3Icon className="w-6 h-6" />
          </button>

          <div className="flex items-center justify-end gap-4">
            <div className="flex items-center">
              <button
                onClick={handleConnectWallet}
                disabled={loading}
                className={`px-4 py-2 rounded-lg text-sm font-medium transition-all duration-300 ${
                  isConnected
                    ? 'bg-gray-100 hover:bg-gray-200 text-gray-800'
                    : 'bg-primary-500 hover:bg-primary-600 text-white'
                } ${loading ? 'opacity-50 cursor-not-allowed' : ''}`}
              >
                {loading ? (
                  <span className="flex items-center">
                    <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-primary-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                    连接中...
                  </span>
                ) : isConnected ? (
                  <span className="flex items-center">
                    <span className="w-2 h-2 bg-green-500 rounded-full mr-2"></span>
                    {formatAddress(account)}
                  </span>
                ) : (
                  '连接钱包'
                )}
              </button>
            </div>
          </div>
        </header>

        {/* 页面内容 */}
        <main className="mx-6 my-6 lg:mx-6">
          <Outlet />
        </main>
      </div>
    </div>
  );
};

export default Layout; 