import React, { useState, useEffect } from 'react';
import { useWeb3 } from '../context/Web3Context';
import GlassCard from '../components/GlassCard';
import { ethers } from 'ethers';
import { formatAmount } from '../utils/contract';
import glassToast from '../utils/toastUtils';
import { 
  CurrencyDollarIcon, 
  InformationCircleIcon,
  ArrowTrendingUpIcon
} from '@heroicons/react/24/outline';
import { Card, CardContent, Typography, TextField, Button, CircularProgress } from '@mui/material';
import { styled } from '@mui/material/styles';
import FeeDecayCounter from '../components/FeeDecayCounter';
import ProgressBar from '../components/ProgressBar';

const MIN_STAKE = ethers.utils.parseEther('100');

const StyledCard = styled(Card)(({ theme }) => ({
  background: 'rgba(255, 255, 255, 0.1)',
  backdropFilter: 'blur(10px)',
  borderRadius: '15px',
  border: '1px solid rgba(255, 255, 255, 0.2)',
  color: 'white',
  height: '100%',
  display: 'flex',
  flexDirection: 'column',
  justifyContent: 'space-between',
  transition: 'transform 0.3s ease-in-out',
  '&:hover': {
    transform: 'translateY(-5px)',
  },
}));

const Staking = () => {
  const { account, contract, tokenContract, isConnected } = useWeb3();
  
  const [amount, setAmount] = useState('');
  const [referrer, setReferrer] = useState('');
  const [loading, setLoading] = useState(false);
  const [tokenBalance, setTokenBalance] = useState('0');
  const [allowance, setAllowance] = useState('0');
  const [userStakes, setUserStakes] = useState([]);
  const [error, setError] = useState(null);
  const [selectedStake, setSelectedStake] = useState(null);
  const [selectedStakeDetails, setSelectedStakeDetails] = useState(null);
  const [withdrawalEstimate, setWithdrawalEstimate] = useState(null);
  const [hasReferrer, setHasReferrer] = useState(false);
  const [userInfo, setUserInfo] = useState({
    totalStaked: '0',
    currentStakingRate: '0',
  });
  const [stakingThresholds, setStakingThresholds] = useState([]);
  const [stakingRates, setStakingRates] = useState([]);
  const [loadingStakingInfo, setLoadingStakingInfo] = useState(false);

  // 从 URL 读取推荐人 (?ref=0x... 或 #/?ref=0x...)
  useEffect(() => {
    try {
      const searchParams = new URLSearchParams(window.location.search);
      let urlRef = searchParams.get('ref');
      if (!urlRef && window.location.hash) {
        const hash = window.location.hash.split('?')[1];
        if (hash) {
          const hashParams = new URLSearchParams(hash);
          urlRef = hashParams.get('ref');
        }
      }
      if (urlRef && /^0x[a-fA-F0-9]{40}$/.test(urlRef)) {
        setReferrer(urlRef);
      }
    } catch (e) {
      console.warn('解析推荐参数失败:', e);
    }
  }, []);

  const checkReferrerStatus = async () => {
    if (!contract || !account) return;
    try {
      const userInfo = await contract.getUserInfo(account);
      console.log('用户信息:', userInfo);
      const hasRef = userInfo.referrer !== '0x0000000000000000000000000000000000000000';
      console.log('是否已有推荐人:', hasRef);
      setHasReferrer(hasRef);
    } catch (error) {
      console.error('获取推荐人状态失败:', error);
    }
  };

    const loadUserData = async () => {
    if (!contract || !account) return;
    try {
      setLoading(true);
      const [balance, allowance, activeStakeIndices] = await Promise.all([
        tokenContract.balanceOf(account),
        tokenContract.allowance(account, contract.address),
        contract.getActiveStakeIndices(account)
      ]);
      
      setTokenBalance(balance.toString());
      setAllowance(allowance.toString());
      
      // 获取所有质押记录
      const stakes = await Promise.all(
        activeStakeIndices.map(async (index) => {
          const stakeDetails = await contract.getStakeDetails(account, index);
          return {
            index: index.toString(),
            amount: stakeDetails.amount.toString(),
            startTime: stakeDetails.startTime.toString(),
            rate: stakeDetails.rate.toString(),
            active: stakeDetails.active
          };
        })
      );
      
        setUserStakes(stakes);
      await checkReferrerStatus();
    } catch (error) {
      console.error('加载用户数据失败:', error);
      glassToast.error('加载用户数据失败: ' + error.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    const init = async () => {
      if (contract && account) {
        try {
          await loadUserData();
        } catch (error) {
          console.error('加载数据失败:', error);
        }
      }
    };
    init();
  }, [contract, account]);

  // 添加一个useEffect来监听hasReferrer的变化
  useEffect(() => {
    console.log('hasReferrer状态更新:', hasReferrer);
  }, [hasReferrer]);

  const handleStake = async (e) => {
    e.preventDefault();
    
    if (!amount || parseFloat(amount) <= 0) {
      glassToast.error('请输入有效的质押金额');
      return;
    }
    
    try {
      const amountWei = ethers.utils.parseUnits(amount, 18);
    if (amountWei.lt(MIN_STAKE)) {
      glassToast.error(`最小质押金额为 ${formatAmount(MIN_STAKE)} 代币`);
      return;
    }
    
      if (amountWei.gt(ethers.utils.parseUnits(tokenBalance, 18))) {
      glassToast.error('余额不足');
      return;
    }
    
    setLoading(true);
      
      // 如果需要授权
      if (ethers.BigNumber.from(allowance).lt(amountWei)) {
        const tx = await tokenContract.approve(contract.address, ethers.constants.MaxUint256);
        glassToast.info('授权交易已提交，请等待确认...');
        await tx.wait();
        glassToast.success('授权成功!');
        
        // 更新授权额度
        const newAllowance = await tokenContract.allowance(account, contract.address);
        setAllowance(newAllowance);
      }
      
      // 执行质押
      const tx = await contract.stake(amountWei, referrer || ethers.constants.AddressZero);
      glassToast.info('质押交易已提交，请等待确认...');
      await tx.wait();
      glassToast.success('质押成功!');
      
      // 重新加载数据
      await loadUserData();
      
      // 清空表单
      setAmount('');
      setReferrer('');
    } catch (error) {
      console.error('质押失败:', error);
      glassToast.error('质押失败: ' + error.message);
    } finally {
      setLoading(false);
    }
  };

  // 格式化时间戳为日期字符串
  const formatDate = (timestamp) => {
    try {
      if (!timestamp || timestamp === '0') return '未领取';
      const date = new Date(Number(timestamp) * 1000);
      if (isNaN(date.getTime())) return '未领取';
      return date.toLocaleString('zh-CN', {
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: false
      });
    } catch (error) {
      console.error('时间格式化错误:', error, '时间戳:', timestamp);
      return '未领取';
    }
  };

  // 格式化金额
  const formatStakeAmount = (amount) => {
    try {
      if (!amount) return '0';
      const formattedAmount = formatAmount(amount);
      return parseFloat(formattedAmount).toLocaleString('zh-CN', {
        minimumFractionDigits: 2,
        maximumFractionDigits: 8
      });
    } catch (error) {
      console.error('金额格式化错误:', error, '金额:', amount);
      return '0';
    }
  };

  // 准备活跃的质押数据
  const activeStakes = [...userStakes]
    .filter(stake => stake.active)
    .sort((a, b) => Number(b.startTime) - Number(a.startTime));

  const handleSelectStake = async (stake) => {
    if (!contract || !account) return;
    try {
      setLoading(true);
      setSelectedStake(stake);
      setWithdrawalEstimate(null);
      
      // 获取质押详情
      const details = await contract.getStakeDetails(account, stake.index);
      console.log('质押详情:', {
        lastClaimTime: details.lastClaimTime.toString(),
        startTime: stake.startTime,
        currentTime: Math.floor(Date.now() / 1000)
      });
      
      const currentTime = Math.floor(Date.now() / 1000);
      const stakeDuration = currentTime - Number(stake.startTime);
      const remainingTime = Math.max(0, 8640000 - stakeDuration); // 100天 = 8640000秒
      const feePercentage = (Number(details.withdrawFee) * 100) / Number(stake.amount);
      
      const stakeWithDetails = {
        ...stake,
        stakeDuration: stakeDuration.toString(),
        remainingFeeDecayTime: remainingTime.toString(),
        currentFeePercentage: feePercentage.toString(),
        pendingReward: details.pendingReward.toString(),
        withdrawFee: details.withdrawFee.toString(),
        lastClaimTime: details.lastClaimTime.toString()
      };
      
      setSelectedStakeDetails(stakeWithDetails);
      
      // 计算提款预估
      const principal = Number(stake.amount) - Number(details.withdrawFee);
      setWithdrawalEstimate({
        principal: principal.toString(),
        reward: details.pendingReward.toString(),
        fee: details.withdrawFee.toString()
      });
    } catch (error) {
      console.error('获取质押详情失败:', error);
      glassToast.error('获取质押详情失败: ' + error.message);
    } finally {
      setLoading(false);
    }
  };

  const handleWithdraw = async (stake) => {
    if (!contract || !account) return;
    
    try {
      setLoading(true);
      
      // 确保stake是一个有效的对象
      if (!stake || typeof stake.index === 'undefined') {
        throw new Error('无效的质押记录');
      }
      
      const tx = await contract.withdraw(stake.index);
      glassToast.info('提款交易已提交，请等待确认...');
      await tx.wait();
      glassToast.success('提款成功!');
      
      // 重新加载数据
      await loadUserData();
      
      // 清空表单
      setAmount('');
      setReferrer('');
      setSelectedStake(null);
      setSelectedStakeDetails(null);
      setWithdrawalEstimate(null);
    } catch (error) {
      console.error('提款失败:', error);
      glassToast.error('提款失败: ' + error.message);
    } finally {
      setLoading(false);
    }
  };

  // 加载质押总量和等级配置
  const loadStakingInfo = async () => {
    if (!contract || !account) return;
    setLoadingStakingInfo(true);
    try {
      const [userInfoArr, allRateConfigs] = await Promise.all([
        contract.getUserInfo(account),
        contract.getAllRateConfigs()
      ]);
      setUserInfo({
        totalStaked: userInfoArr[0]?.toString() || '0',
        currentStakingRate: userInfoArr[3]?.toString() || '0',
      });
      setStakingThresholds(allRateConfigs[0].map(r => r.threshold));
      setStakingRates(allRateConfigs[0].map(r => r.rate));
    } catch (e) {
      glassToast.error('加载质押等级信息失败: ' + e.message);
    } finally {
      setLoadingStakingInfo(false);
    }
  };

  useEffect(() => {
    loadStakingInfo();
  }, [contract, account]);

  // 计算当前等级、下一等级、进度等
  const totalStakedNum = parseFloat(formatAmount(userInfo.totalStaked || '0'));
  let currentLevel = 0;
  let nextLevel = 0;
  let nextRate = 0;
  if (stakingThresholds.length > 0) {
    for (let i = 0; i < stakingThresholds.length; i++) {
      if (totalStakedNum >= parseFloat(formatAmount(stakingThresholds[i]))) {
        currentLevel = i;
      }
    }
    nextLevel = currentLevel + 1;
    if (nextLevel < stakingThresholds.length) {
      nextRate = parseFloat(stakingRates[nextLevel]) / 10000;
    } else {
      nextRate = null;
    }
  }
  const progress = nextRate ? Math.min(100, (totalStakedNum / parseFloat(formatAmount(stakingThresholds[nextLevel]))) * 100) : 100;
  const needForNext = nextRate ? (parseFloat(formatAmount(stakingThresholds[nextLevel])) - totalStakedNum) : 0;

  // 未连接钱包时显示的内容
  if (!isConnected) {
    return (
      <div className="min-h-[70vh] flex flex-col items-center justify-center">
        <GlassCard className="max-w-md w-full text-center p-8">
          <h2 className="text-2xl font-bold text-primary-700 mb-4">质押中心</h2>
          <p className="text-gray-600 mb-6">连接您的钱包以查看您的质押和收益数据</p>
          <p className="text-sm text-gray-600 mt-4">质押代币并邀请朋友可以获得更多收益</p>
        </GlassCard>
      </div>
    );
  }

  if (loading) {
    return (
      <div className="min-h-[70vh] flex flex-col items-center justify-center">
        <div className="text-center">
          <CircularProgress className="text-primary-600" />
          <p className="mt-4 text-gray-600">加载中...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-[70vh] flex flex-col items-center justify-center">
        <GlassCard className="max-w-md w-full text-center p-8">
          <h2 className="text-2xl font-bold text-red-600 mb-4">加载失败</h2>
          <p className="text-gray-600">{error}</p>
          <button 
            onClick={() => window.location.reload()} 
            className="mt-4 glass px-4 py-2 text-primary-600 hover:bg-white/40"
          >
            重试
          </button>
        </GlassCard>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* 质押表单 */}
        <div className="lg:col-span-1">
          <StyledCard>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                质押
              </Typography>
              <div className="glass p-6 rounded-xl">
                <h3 className="text-xl font-semibold mb-4 text-primary-800">质押代币</h3>
                <div className="space-y-4">
              <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">质押数量</label>
                  <input
                    type="number"
                    value={amount}
                    onChange={(e) => setAmount(e.target.value)}
                      placeholder="输入质押数量"
                      className="w-full p-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-primary-500 bg-white text-gray-800 placeholder-gray-500"
                  />
                  </div>
                  
                  {!hasReferrer && (
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">推荐人地址（可选）</label>
                      <input
                        type="text"
                        value={referrer}
                        onChange={(e) => setReferrer(e.target.value)}
                        placeholder="输入推荐人地址"
                        className="w-full p-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-primary-500 bg-white text-gray-800 placeholder-gray-500"
                      />
                </div>
                  )}
                  
                  <button 
                    onClick={handleStake}
                    disabled={loading || !amount}
                    className="w-full btn btn-gold"
                  >
                    {loading ? '处理中...' : '质押'}
                  </button>
                </div>
              </div>
            </CardContent>
          </StyledCard>
              </div>
              
        {/* 质押进度卡片 */}
        <div className="lg:col-span-1">
          <GlassCard 
            title="质押等级进度" 
            icon={<ArrowTrendingUpIcon className="h-5 w-5 text-primary-600" />}
          >
            {totalStakedNum > 0 ? (
              <>
                <div className="mb-3">
                  <span className="text-sm text-gray-600">
                    当前质押率: <span className="font-medium text-primary-600">{(parseFloat(userInfo.currentStakingRate) / 10000).toFixed(3)}%</span>
                  </span>
                  {nextRate !== null && (
                    <>
                      <span className="mx-2 text-gray-400">|</span>
                      <span className="text-sm text-gray-600">
                        下一等级质押率: <span className="font-medium text-accent-600">{nextRate.toFixed(3)}%</span>
                      </span>
                    </>
                  )}
                </div>
                <div className="mb-2">
                  <span className="text-sm text-gray-600">
                    当前质押量: <span className="font-medium text-primary-600">{totalStakedNum.toLocaleString()} AOT</span>
                  </span>
                </div>
                {nextRate !== null && (
                  <>
                    <div className="mb-1 text-sm text-gray-600">
                      距离下一等级还需
                      <span className="ml-2 font-semibold text-primary-600">{totalStakedNum.toLocaleString()}</span>
                      <span className="mx-1">/</span>
                      <span className="font-semibold text-accent-600">{parseFloat(formatAmount(stakingThresholds[nextLevel])).toLocaleString()}</span>
                      <span className="ml-2">({progress.toFixed(1)}%)</span>
                  </div>
                    <div className="w-full bg-gray-200 rounded-full h-2.5 mb-1">
                      <div className="bg-gradient-to-r from-bluebrand-400 to-primary-500 h-2.5 rounded-full transition-all duration-500" style={{ width: `${progress}%` }}></div>
                </div>
                    <p className="text-xs text-gray-500 mt-2">
                      再质押 <span className="font-semibold text-accent-600">{needForNext.toLocaleString()}</span> AOT质押量即可升级
                    </p>
                  </>
                )}
                {nextRate === null && (
                  <p className="text-center text-green-600 py-4">恭喜，您已达到最高质押等级!</p>
                )}
              </>
            ) : (
              <p className="text-center text-gray-600 py-4">尚未有质押记录</p>
            )}
          </GlassCard>
        </div>
        
        {/* 质押列表和详情 */}
        <div className="lg:col-span-2 space-y-6">
          <GlassCard title="我的质押" icon={<CurrencyDollarIcon className="h-5 w-5 text-primary-600" />}>
            {activeStakes.length > 0 ? (
              <div className="mt-3">
                {activeStakes.map((stake, index) => (
                  <div
                    key={index}
                    onClick={() => handleSelectStake(stake)}
                    className={`glass p-4 rounded-lg cursor-pointer mb-3 transition-all duration-300 relative ${
                      selectedStake === stake
                        ? 'bg-gradient-to-r from-primary-50/90 to-white/95 border-2 border-primary-500 shadow-xl scale-[1.02] transform'
                        : 'hover:bg-white/40 border border-transparent hover:border-primary-200'
                    }`}
                  >
                    {selectedStake === stake && (
                      <>
                        <div className="absolute -left-2 top-1/2 -translate-y-1/2 w-1 h-12 bg-primary-500 rounded-full shadow-lg" />
                        <div className="absolute -right-1 top-1/2 -translate-y-1/2 w-1 h-8 bg-accent-500/70 rounded-full shadow-lg" />
                      </>
                    )}
                    <div className="flex justify-between items-center">
                      <div>
                        <p className={`text-sm ${selectedStake === stake ? 'text-primary-900 font-medium' : 'text-gray-600'}`}>
                          开始时间: {formatDate(stake.startTime)}
                        </p>
                        <p className={`text-xl font-semibold mt-2 ${
                          selectedStake === stake ? 'text-primary-800' : 'text-primary-700'
                        }`}>
                          {formatStakeAmount(stake.amount)} AOT
                        </p>
                      </div>
                      <div className="text-right">
                        <p className={`text-sm ${selectedStake === stake ? 'text-primary-900 font-medium' : 'text-gray-600'}`}>
                          收益率: <span className={`${selectedStake === stake ? 'text-accent-800' : 'text-accent-600'} font-semibold`}>
                            {(parseInt(stake.rate) / 10000).toFixed(3)}%
                          </span>
                        </p>
                        <p className={`text-sm mt-2 ${selectedStake === stake ? 'text-primary-900 font-medium' : 'text-gray-600'}`}>
                          状态: <span className={`${
                            selectedStake === stake 
                              ? 'bg-green-50 text-green-800 border border-green-200' 
                              : 'text-green-600'
                          } font-semibold px-2 py-0.5 rounded`}>活跃</span>
                        </p>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="text-center py-8">
                <p className="text-gray-600">您还没有活跃的质押</p>
              </div>
            )}
          </GlassCard>
          
          {/* 选中的质押详情 */}
          {selectedStakeDetails && (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <GlassCard 
                title="质押详情" 
                icon={<InformationCircleIcon className="h-5 w-5 text-primary-600" />}
                className="border-2 border-primary-500/30"
              >
                <div className="space-y-3 mt-2">
                  <div className="flex justify-between">
                    <span className="text-gray-600">质押金额:</span>
                    <span className="font-medium">{parseFloat(formatAmount(selectedStakeDetails.amount)).toLocaleString()} AOT</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-gray-600">收益率:</span>
                    <span className="font-medium">{(selectedStakeDetails.rate / 10000).toFixed(3)}% 每日</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-gray-600">开始日期:</span>
                    <span className="font-medium">{formatDate(selectedStakeDetails.startTime)}</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-gray-600">上次领取:</span>
                    <span className="font-medium">{formatDate(selectedStakeDetails.lastClaimTime)}</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-gray-600">待领取奖励:</span>
                    <span className="font-medium text-accent-600">{parseFloat(formatAmount(selectedStakeDetails.pendingReward)).toLocaleString()} AOT</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-gray-600">当前提款费用:</span>
                    <span className="font-medium text-amber-600">
                      {parseFloat(formatAmount(selectedStakeDetails.withdrawFee)).toLocaleString()} AOT 
                      ({((Number(selectedStakeDetails.withdrawFee) * 100) / Number(selectedStakeDetails.amount)).toFixed(2)}%)
                    </span>
                  </div>
                </div>
                
                {withdrawalEstimate && (
                  <div className="mt-6 pt-4 border-t border-white/20">
                    <h4 className="text-base font-medium text-primary-700 mb-3">提款预估</h4>
                    <div className="space-y-2">
                      <div className="flex justify-between">
                        <span className="text-gray-600">获得本金:</span>
                        <span className="font-medium">{parseFloat(formatAmount(withdrawalEstimate.principal)).toLocaleString()} AOT</span>
                      </div>
                      <div className="flex justify-between">
                        <span className="text-gray-600">获得奖励:</span>
                        <span className="font-medium text-accent-600">{parseFloat(formatAmount(withdrawalEstimate.reward)).toLocaleString()} AOT</span>
                      </div>
                      <div className="flex justify-between">
                        <span className="text-gray-600">提款手续费:</span>
                        <span className="font-medium text-amber-600">{parseFloat(formatAmount(withdrawalEstimate.fee)).toLocaleString()} AOT</span>
                      </div>
                      <div className="flex justify-between font-medium pt-2 mt-2 border-t border-white/20">
                        <span>总计获得:</span>
                        <span className="text-primary-700">
                          {(parseFloat(formatAmount(withdrawalEstimate.principal)) + parseFloat(formatAmount(withdrawalEstimate.reward))).toLocaleString()} AOT
                        </span>
                      </div>
                    </div>
                    
                    <button
                      onClick={() => handleWithdraw(selectedStakeDetails)}
                      disabled={loading}
                      className="mt-4 w-full btn btn-gold"
                    >
                      {loading ? '处理中...' : '提款'}
                    </button>
                  </div>
                )}
              </GlassCard>
              
              {selectedStakeDetails && (
                <FeeDecayCounter
                  remainingTime={Number(selectedStakeDetails.remainingFeeDecayTime)}
                  currentFeePercentage={Number(selectedStakeDetails.currentFeePercentage)}
                  stakeDuration={Number(selectedStakeDetails.stakeDuration || 0)}
                />
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Staking; 