// 获取合约实例
export const getContract = (provider) => {
  if (!provider) {
    console.error('Provider未初始化');
    return null;
  }
  
  try {
    console.log('创建合约实例...');
    console.log('合约地址:', CONTRACT_ADDRESS);
    console.log('合约ABI:', CONTRACT_ABI);
    
    const contract = new ethers.Contract(CONTRACT_ADDRESS, CONTRACT_ABI, provider);
    console.log('合约实例创建成功:', contract);
    return contract;
  } catch (error) {
    console.error('创建合约实例失败:', error);
    return null;
  }
};

// 获取代币合约实例
export const getTokenContract = (provider, tokenAddress = TOKEN_ADDRESS) => {
  if (!provider) {
    console.error('Provider未初始化');
    return null;
  }
  
  try {
    console.log('创建代币合约实例...');
    console.log('代币合约地址:', tokenAddress);
    console.log('代币合约ABI:', TOKEN_ABI);
    
    const contract = new ethers.Contract(tokenAddress, TOKEN_ABI, provider);
    console.log('代币合约实例创建成功:', contract);
    return contract;
  } catch (error) {
    console.error('创建代币合约实例失败:', error);
    return null;
  }
};

// 格式化金额
export const formatAmount = (amount, decimals = 18) => {
  if (!amount) return '0';
  return (Number(amount) / Math.pow(10, decimals)).toFixed(4);
};

// 解析金额
export const parseAmount = (amount, decimals = 18) => {
  if (!amount) return '0';
  return (Number(amount) * Math.pow(10, decimals)).toString();
}; 