import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { ethers } from 'ethers';
import { getContract, getTokenContract, NETWORKS, CONTRACT_ABI, TOKEN_ABI, CONTRACT_ADDRESS, TOKEN_ADDRESS } from '../utils/contract';
import glassToast from '../utils/toastUtils';

const Web3Context = createContext();

export const Web3Provider = ({ children }) => {
  const [account, setAccount] = useState(null);
  const [contract, setContract] = useState(null);
  const [tokenContract, setTokenContract] = useState(null);
  const [isConnected, setIsConnected] = useState(false);
  const [chainId, setChainId] = useState(null);
  const [provider, setProvider] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [isInitialized, setIsInitialized] = useState(false);
  const [signer, setSigner] = useState(null);

  // 检查是否安装了 MetaMask
  const checkIfWalletIsInstalled = useCallback(() => {
    if (!window.ethereum) {
      console.error('请安装 MetaMask!');
      return false;
    }
    return true;
  }, []);

  // 检查网络
  const checkNetwork = async () => {
    try {
      if (!provider) {
        console.log('Provider not initialized');
        return false;
      }

      const network = await provider.getNetwork();
      console.log('当前网络详情:', {
        chainId: network.chainId.toString(),
        name: network.name,
        provider: provider.constructor.name
      });
      
      // 将 chainId 转换为数字进行比较
      const currentChainId = Number(network.chainId);
      const targetChainId = 11155111; // Sepolia 的 chainId
      
      console.log('网络检查:', {
        当前chainId: currentChainId,
        目标chainId: targetChainId,
        是否匹配: currentChainId === targetChainId
      });
      
      if (currentChainId !== targetChainId) {
        console.log('需要切换网络到 Sepolia');
        try {
          // 先尝试切换网络
          await window.ethereum.request({
            method: 'wallet_switchEthereumChain',
            params: [{ chainId: '0xaa36a7' }], // Sepolia 的 chainId (十六进制)
          });
          console.log('成功切换到 Sepolia 网络');
          return true;
        } catch (switchError) {
          console.error('切换网络失败:', switchError);
          
          // 如果网络未添加，则添加网络
          if (switchError.code === 4902) {
            console.log('尝试添加 Sepolia 网络');
            try {
              await window.ethereum.request({
                method: 'wallet_addEthereumChain',
                params: [{
                  chainId: '0xaa36a7',
                  chainName: 'Sepolia',
                  nativeCurrency: {
                    name: 'SepoliaETH',
                    symbol: 'SepoliaETH',
                    decimals: 18
                  },
                  rpcUrls: ['https://rpc.sepolia.org'],
                  blockExplorerUrls: ['https://sepolia.etherscan.io']
                }]
              });
              console.log('成功添加 Sepolia 网络');
              return true;
            } catch (addError) {
              console.error('添加网络失败:', addError);
              throw new Error('请手动添加 Sepolia 测试网');
            }
          }
          throw new Error('请手动切换到 Sepolia 测试网');
        }
      }
      
      console.log('已在 Sepolia 网络上');
      return true;
    } catch (error) {
      console.error('检查网络失败:', error);
      throw error;
    }
  };

  // 连接钱包
  const connectWallet = async () => {
    try {
      console.log('开始连接钱包...');
      
      // 检查是否安装了 MetaMask
      if (!window.ethereum) {
        throw new Error('请安装 MetaMask 钱包');
      }

      // 请求连接钱包
      const accounts = await window.ethereum.request({ method: 'eth_requestAccounts' });
      console.log('连接钱包成功，账户:', accounts);
      
      if (!accounts || accounts.length === 0) {
        throw new Error('未获取到账户');
      }

      // 获取当前网络
      const chainId = await window.ethereum.request({ method: 'eth_chainId' });
      console.log('当前网络 chainId:', chainId);
      
      // 检查是否是 Sepolia 网络
      if (chainId !== '0xaa36a7') {
        try {
          // 尝试切换网络
          await window.ethereum.request({
            method: 'wallet_switchEthereumChain',
            params: [{ chainId: '0xaa36a7' }],
          });
          console.log('成功切换到 Sepolia 网络');
        } catch (switchError) {
          console.error('切换网络失败:', switchError);
          if (switchError.code === 4902) {
            try {
              await window.ethereum.request({
                method: 'wallet_addEthereumChain',
                params: [{
                  chainId: '0xaa36a7',
                  chainName: 'Sepolia',
                  nativeCurrency: {
                    name: 'SepoliaETH',
                    symbol: 'SepoliaETH',
                    decimals: 18
                  },
                  rpcUrls: ['https://rpc.sepolia.org'],
                  blockExplorerUrls: ['https://sepolia.etherscan.io']
                }]
              });
              console.log('成功添加 Sepolia 网络');
            } catch (addError) {
              console.error('添加网络失败:', addError);
              throw new Error('请手动添加 Sepolia 测试网');
            }
          } else {
            throw new Error('请手动切换到 Sepolia 测试网');
          }
        }
      }

      // 创建 provider
      const provider = new ethers.providers.Web3Provider(window.ethereum);
      console.log('Provider 创建成功:', provider);

      // 获取签名者
      const signer = provider.getSigner();
      console.log('Signer 创建成功:', signer);

      // 获取合约实例
      const contract = getContract(signer);
      console.log('合约实例创建成功:', contract);

      // 获取代币合约实例
      const tokenContract = getTokenContract(signer);
      console.log('代币合约实例创建成功:', tokenContract);

      // 更新状态
      setProvider(provider);
      setSigner(signer);
      setContract(contract);
      setTokenContract(tokenContract);
      setAccount(accounts[0]);
      setIsConnected(true);
      setError(null);

      // 监听账户变化
      const handleAccountsChanged = (accounts) => {
        if (accounts.length === 0) {
          disconnectWallet();
        } else {
          setAccount(accounts[0]);
        }
      };

      // 监听网络变化
      const handleChainChanged = () => {
        window.location.reload();
      };

      window.ethereum.on('accountsChanged', handleAccountsChanged);
      window.ethereum.on('chainChanged', handleChainChanged);

      console.log('钱包连接完成');
    } catch (error) {
      console.error('连接钱包失败:', error);
      setError(error.message);
      setIsConnected(false);
      setAccount(null);
      setProvider(null);
      setSigner(null);
      setContract(null);
      setTokenContract(null);
      glassToast.error('连接钱包失败: ' + error.message);
    }
  };

  // 断开连接
  const disconnectWallet = useCallback(() => {
    setAccount(null);
    setContract(null);
    setTokenContract(null);
    setIsConnected(false);
    setChainId(null);
    setProvider(null);
    setSigner(null);
  }, []);

  // 格式化地址
  const formatAddress = useCallback((address) => {
    if (!address) return '';
    return `${address.substring(0, 6)}...${address.substring(address.length - 4)}`;
  }, []);

  // 监听账户变化
  useEffect(() => {
    if (!window.ethereum) return;

    const handleAccountsChanged = (accounts) => {
      if (accounts.length === 0) {
        disconnectWallet();
      } else {
        setAccount(accounts[0]);
      }
    };

    const handleChainChanged = () => {
      window.location.reload();
    };

    window.ethereum.on('accountsChanged', handleAccountsChanged);
    window.ethereum.on('chainChanged', handleChainChanged);

    return () => {
      window.ethereum.removeListener('accountsChanged', handleAccountsChanged);
      window.ethereum.removeListener('chainChanged', handleChainChanged);
    };
  }, [disconnectWallet]);

  // 自动连接
  useEffect(() => {
    let mounted = true;
    
    const autoConnect = async () => {
      if (!window.ethereum) {
        console.log('未检测到MetaMask');
        setLoading(false);
        return;
      }
      
      try {
        console.log('开始自动连接...');
        setLoading(true);
        
        // 检查是否已经连接
        const accounts = await window.ethereum.request({ method: 'eth_accounts' });
        console.log('当前已连接账户:', accounts);
        
        if (accounts.length === 0) {
          console.log('没有已连接的账户');
          setLoading(false);
          return;
        }
        
        // 检查网络
        const chainId = await window.ethereum.request({ method: 'eth_chainId' });
        console.log('当前链ID:', chainId);
        
        // 将链ID转换为数字进行比较
        const currentChainId = parseInt(chainId, 16);
        const targetChainId = parseInt('0xaa36a7', 16);
        console.log('当前链ID(数字):', currentChainId);
        console.log('目标链ID(数字):', targetChainId);
        
        if (currentChainId !== targetChainId) {
          console.log('不在Sepolia网络上，尝试切换...');
          try {
            await window.ethereum.request({
              method: 'wallet_switchEthereumChain',
              params: [{ chainId: '0xaa36a7' }],
            });
            console.log('成功切换到Sepolia网络');
          } catch (switchError) {
            console.error('切换网络失败:', switchError);
            setError('请切换到Sepolia测试网');
            setLoading(false);
            return;
          }
        }
        
        // 初始化provider和signer
        const provider = new ethers.providers.Web3Provider(window.ethereum);
        const signer = provider.getSigner();
        
        // 检查合约是否已部署
        const code = await provider.getCode(CONTRACT_ADDRESS);
        console.log('合约代码:', code);
        if (code === '0x') {
          console.error('合约未部署到该地址');
          setError('合约未部署到该地址');
          setLoading(false);
          return;
        }
        
        // 初始化合约
        const contract = new ethers.Contract(CONTRACT_ADDRESS, CONTRACT_ABI, signer);
        const tokenContract = new ethers.Contract(TOKEN_ADDRESS, TOKEN_ABI, signer);
        
        if (mounted) {
          setAccount(accounts[0]);
          setContract(contract);
          setTokenContract(tokenContract);
          setIsConnected(true);
          setError(null);
          console.log('自动连接成功');
        }
      } catch (error) {
        console.error('自动连接失败:', error);
        setError(error.message);
      } finally {
        if (mounted) {
          setLoading(false);
        }
      }
    };
    
    autoConnect();
    
    return () => {
      mounted = false;
    };
  }, []);

  // 初始化 Web3
  const initWeb3 = async () => {
    try {
      console.log('开始初始化 Web3...');
      
      if (!window.ethereum) {
        throw new Error('请安装 MetaMask 钱包');
      }

      // 创建 provider
      const provider = new ethers.providers.Web3Provider(window.ethereum);
      console.log('Provider 创建成功:', provider.constructor.name);

      // 获取 signer
      const signer = provider.getSigner();
      console.log('Signer 创建成功');

      // 检查网络
      await checkNetwork();

      // 创建合约实例
      const contract = new ethers.Contract(CONTRACT_ADDRESS, CONTRACT_ABI, signer);
      console.log('合约实例创建成功:', {
        地址: contract.address,
        方法: Object.keys(contract.functions)
      });

      // 创建代币合约实例
      const tokenContract = new ethers.Contract(TOKEN_ADDRESS, TOKEN_ABI, signer);
      console.log('代币合约实例创建成功:', {
        地址: tokenContract.address,
        方法: Object.keys(tokenContract.functions)
      });

      setProvider(provider);
      setContract(contract);
      setTokenContract(tokenContract);
      setIsInitialized(true);
      console.log('Web3 初始化完成');
    } catch (error) {
      console.error('初始化 Web3 失败:', error);
      setError(error.message);
      setIsInitialized(false);
    }
  };

  const value = {
    account,
    contract,
    tokenContract,
    isConnected,
    chainId,
    provider,
    connectWallet,
    disconnectWallet,
    formatAddress,
    loading,
    error
  };

  return (
    <Web3Context.Provider value={value}>
      {children}
    </Web3Context.Provider>
  );
};

export const useWeb3 = () => {
  const context = useContext(Web3Context);
  if (!context) {
    throw new Error('useWeb3 must be used within a Web3Provider');
  }
  return context;
}; 