import React, { useState, useEffect } from 'react';
import { useWeb3 } from '../context/Web3Context';
import GlassCard from '../components/GlassCard';
import ProgressBar from '../components/ProgressBar';
import { formatAmount } from '../utils/contract';
import { 
  CurrencyDollarIcon, 
  UserGroupIcon, 
  ChartBarIcon,
  FireIcon,
  ArrowTrendingUpIcon,
  ArrowPathIcon
} from '@heroicons/react/24/outline';
import { Link } from 'react-router-dom';
import { glassToast } from '../contexts/GlassToastContext';
import { Card, CardContent, Typography, Grid, Button, CircularProgress } from '@mui/material';
import { styled } from '@mui/material/styles';
import { ethers } from 'ethers';

const StyledCard = styled(Card)(({ theme }) => ({
  background: 'rgba(255, 255, 255, 0.1)',
  backdropFilter: 'blur(10px)',
  borderRadius: '15px',
  border: '1px solid rgba(255, 255, 255, 0.2)',
  color: 'white',
  height: '100%',
  display: 'flex',
  flexDirection: 'column',
  justifyContent: 'space-between',
  transition: 'transform 0.3s ease-in-out',
  '&:hover': {
    transform: 'translateY(-5px)',
  },
}));

const Dashboard = () => {
  const { account, contract, tokenContract, isConnected } = useWeb3();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [userData, setUserData] = useState({
    totalStaked: '0',
    pendingRewards: '0',
    tokenBalance: '0',
    stakingRate: '0',
    referralRate: '0',
    referralEarnings: '0'
  });

  useEffect(() => {
    const init = async () => {
      if (contract && account) {
        try {
          setLoading(true);
          setError(null);
          await loadUserData();
        } catch (error) {
          console.error('加载数据失败:', error);
          setError(error.message);
        } finally {
          setLoading(false);
        }
      } else {
        setLoading(false);
        setError(null);
      }
    };
    init();
  }, [contract, account]);

  const loadUserData = async () => {
    if (!contract || !account) {
      console.log('合约或账户未初始化:', { contract, account });
      return;
    }

    try {
      console.log('开始加载用户数据...');
      console.log('合约地址:', contract.address);
      console.log('用户地址:', account);
      
      // 检查合约是否已部署
      const code = await contract.provider.getCode(contract.address);
      console.log('合约代码:', code);
      if (code === '0x') {
        throw new Error('合约未部署');
      }

      // 获取用户信息
      const [userTotalStaked, referrer, totalReferred, currentStakingRate, currentReferralRate] = await contract.getUserInfo(account);
      console.log('用户信息:', {
        userTotalStaked: formatAmount(userTotalStaked),
        referrer,
        totalReferred: formatAmount(totalReferred),
        currentStakingRate: currentStakingRate.toString(),
        currentReferralRate: currentReferralRate.toString()
      });

      // 获取待领取奖励
      const rewards = await contract.getPendingRewards(account);
      console.log('待领取奖励:', formatAmount(rewards));

      // 获取代币余额
      const balance = await tokenContract.balanceOf(account);
      console.log('代币余额:', formatAmount(balance));

      // 获取推荐收益
      const referralEarnings = await contract.getUserReferralEarnings(account);
      console.log('推荐收益:', formatAmount(referralEarnings));

      // 更新状态
      setUserData({
        totalStaked: formatAmount(userTotalStaked),
        pendingRewards: formatAmount(rewards),
        tokenBalance: formatAmount(balance),
        stakingRate: currentStakingRate.toString(),
        referralRate: currentReferralRate.toString(),
        referralEarnings: formatAmount(referralEarnings)
      });

      // 清除任何之前的错误
      setError(null);
    } catch (error) {
      console.error('加载用户数据失败:', error);
      setError(error.message);
      glassToast.error('加载数据失败: ' + error.message);
      throw error; // 重新抛出错误，让 useEffect 捕获
    }
  };

  const handleClaimRewards = async () => {
    if (!contract) return;
    try {
      setLoading(true);
      const tx = await contract.claimAllRewards();
      await tx.wait();
      glassToast.success('收益领取成功');
      loadUserData();
    } catch (error) {
      console.error('领取收益失败:', error);
      glassToast.error('领取收益失败: ' + error.message);
    } finally {
      setLoading(false);
    }
  };

  if (!isConnected) {
    return (
      <div className="min-h-[70vh] flex flex-col items-center justify-center">
        <GlassCard className="max-w-md w-full text-center p-8">
          <h2 className="text-2xl font-bold text-primary-700 mb-4">仪表盘</h2>
          <p className="text-gray-600 mb-6">连接您的钱包以查看您的质押和收益数据</p>
          <p className="text-sm text-gray-600 mt-4">质押代币并邀请朋友可以获得更多收益</p>
        </GlassCard>
      </div>
    );
  }

  if (loading) {
    return (
      <div className="min-h-[70vh] flex flex-col items-center justify-center">
        <div className="text-center">
          <CircularProgress className="text-primary-600" />
          <p className="mt-4 text-gray-600">加载中...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-[70vh] flex flex-col items-center justify-center">
        <GlassCard className="max-w-md w-full text-center p-8">
          <h2 className="text-2xl font-bold text-red-600 mb-4">加载失败</h2>
          <p className="text-gray-600">{error}</p>
          <button 
            onClick={() => window.location.reload()} 
            className="mt-4 glass px-4 py-2 text-primary-600 hover:bg-white/40"
          >
            重试
          </button>
        </GlassCard>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        <GlassCard 
          title="总质押量" 
          icon={<CurrencyDollarIcon className="h-5 w-5 text-primary-600" />}
        >
          <div className="mt-3">
            <p className="text-2xl font-semibold text-primary-700">
              {parseFloat(userData.totalStaked).toLocaleString()} AOT
            </p>
            <p className="text-sm text-gray-600 mt-2">
              您的总质押金额，质押越多收益越高
            </p>
          </div>
        </GlassCard>

        <GlassCard 
          title="待领取收益" 
          icon={<FireIcon className="h-5 w-5 text-accent-600" />}
        >
          <div className="mt-3">
            <p className="text-2xl font-semibold text-accent-600">
              {parseFloat(userData.pendingRewards).toLocaleString()} AOT
            </p>
            <p className="text-sm text-gray-600 mt-2">
              您可以随时领取的质押收益
            </p>
            <button
              onClick={handleClaimRewards}
              disabled={loading || userData.pendingRewards === '0'}
              className="mt-4 w-full btn btn-gold"
            >
              {loading ? '处理中...' : '领取收益'}
            </button>
          </div>
        </GlassCard>

        <GlassCard 
          title="代币余额" 
          icon={<ChartBarIcon className="h-5 w-5 text-primary-600" />}
        >
          <div className="mt-3">
            <p className="text-2xl font-semibold text-primary-700">
              {parseFloat(userData.tokenBalance).toLocaleString()} AOT
            </p>
            <p className="text-sm text-gray-600 mt-2">
              您的钱包中的AOT代币余额
            </p>
          </div>
        </GlassCard>

        <GlassCard 
          title="当前质押率" 
          icon={<ArrowTrendingUpIcon className="h-5 w-5 text-primary-600" />}
        >
          <div className="mt-3">
            <p className="text-2xl font-semibold text-primary-700">
              {(parseFloat(userData.stakingRate) / 10000).toFixed(3)}%
            </p>
            <p className="text-sm text-gray-600 mt-2">
              根据您的质押量计算的年化收益率
            </p>
          </div>
        </GlassCard>

        <GlassCard 
          title="当前推荐率" 
          icon={<UserGroupIcon className="h-5 w-5 text-primary-600" />}
        >
          <div className="mt-3">
            <p className="text-2xl font-semibold text-primary-700">
              {(parseFloat(userData.referralRate) / 10000).toFixed(2)}%
            </p>
            <p className="text-sm text-gray-600 mt-2">
              您从推荐用户获得的奖励比例
            </p>
          </div>
        </GlassCard>

        <GlassCard 
          title="推荐收益" 
          icon={<CurrencyDollarIcon className="h-5 w-5 text-accent-600" />}
        >
          <div className="mt-3">
            <p className="text-2xl font-semibold text-accent-600">
              {parseFloat(userData.referralEarnings).toLocaleString()} AOT
            </p>
            <p className="text-sm text-gray-600 mt-2">
              您从推荐系统中获得的总收益
            </p>
          </div>
        </GlassCard>
      </div>
    </div>
  );
};

export default Dashboard; 