import React from 'react';
import { 
  CheckCircleIcon, 
  ExclamationCircleIcon, 
  InformationCircleIcon, 
  XCircleIcon 
} from '@heroicons/react/24/outline';
import classNames from 'classnames';

const GlassToast = ({ children, type = 'info', onClose }) => {
  // 不同类型的Toast的图标和样式
  const icons = {
    success: <CheckCircleIcon className="h-6 w-6 text-green-600" />,
    error: <XCircleIcon className="h-6 w-6 text-primary-600" />,
    info: <InformationCircleIcon className="h-6 w-6 text-bluebrand-600" />,
    warning: <ExclamationCircleIcon className="h-6 w-6 text-gold-700" />
  };

  // 背景和边框颜色
  const colorClasses = {
    success: 'border-green-400/70',
    error: 'border-primary-400/70',
    info: 'border-bluebrand-400/70',
    warning: 'border-gold-400/70'
  };

  // 渐变背景色
  const gradientStyles = {
    success: 'linear-gradient(135deg, rgba(16,185,129,0.12), rgba(5,150,105,0.18))',
    error: 'linear-gradient(135deg, rgba(232,74,86,0.12), rgba(197,27,39,0.18))',
    info: 'linear-gradient(135deg, rgba(61,124,211,0.12), rgba(38,94,169,0.18))',
    warning: 'linear-gradient(135deg, rgba(241,223,157,0.25), rgba(212,180,103,0.35))'
  };

  return (
    <div 
      className={classNames(
        'glass-toast border',
        'flex items-center p-4 rounded-lg min-w-[300px] max-w-md',
        'bg-white text-gray-800',
        colorClasses[type]
      )}
      style={{
        background: gradientStyles[type],
        backdropFilter: 'blur(6px)',
        boxShadow: '0 10px 28px rgba(0, 0, 0, 0.12)'
      }}
    >
      <div className="mr-3 flex-shrink-0">
        {icons[type]}
      </div>
      <div className="flex-grow text-gray-800">{children}</div>
      {onClose && (
        <button 
          className="ml-3 flex-shrink-0 text-gray-400 hover:text-gray-700"
          onClick={onClose}
        >
          <XCircleIcon className="h-5 w-5" />
        </button>
      )}
    </div>
  );
};

export default GlassToast; 