import React from 'react';
import Countdown from 'react-countdown';
import GlassCard from './GlassCard';
import { ClockIcon } from '@heroicons/react/24/outline';

const FeeDecayCounter = ({ 
  remainingTime, // 以秒为单位的剩余时间
  currentFeePercentage,
  stakeDuration,
  decayPeriod = 8640000, // 100天 (秒)
}) => {
  // 计算百分比进度
  const progress = Math.min(100, (stakeDuration / decayPeriod) * 100);
  
  // 格式化天数
  const formatDays = (seconds) => {
    return Math.floor(seconds / 86400); // 将秒转换为天
  };
  
  // 计算已质押天数
  const stakedDays = formatDays(stakeDuration);
  
  // 计算剩余天数
  const remainingDays = formatDays(remainingTime);
  
  // Countdown 渲染器
  const renderer = ({ days, hours, minutes, seconds, completed }) => {
    if (completed) {
      return <span className="text-green-600 font-medium">费用已减至0%!</span>;
    } else {
      return (
        <div>
          <div className="flex gap-2 justify-center">
            <div className="glass text-center p-2 w-16">
              <div className="text-lg font-semibold">{days}</div>
              <div className="text-xs text-gray-600">天</div>
            </div>
            <div className="glass text-center p-2 w-14">
              <div className="text-lg font-semibold">{hours}</div>
              <div className="text-xs text-gray-600">时</div>
            </div>
            <div className="glass text-center p-2 w-14">
              <div className="text-lg font-semibold">{minutes}</div>
              <div className="text-xs text-gray-600">分</div>
            </div>
            <div className="glass text-center p-2 w-14">
              <div className="text-lg font-semibold">{seconds}</div>
              <div className="text-xs text-gray-600">秒</div>
            </div>
          </div>
        </div>
      );
    }
  };

  return (
    <GlassCard 
      title="费用递减倒计时" 
      icon={<ClockIcon className="h-5 w-5 text-primary-600" />}
    >
      <div className="text-center">
        <div className="space-y-2 mb-4">
          <div className="flex justify-between text-sm">
            <span className="text-gray-600">当前提款费用:</span>
            <span className="font-medium text-primary-600">{currentFeePercentage.toFixed(2)}%</span>
          </div>
          <div className="flex justify-between text-sm">
            <span className="text-gray-600">已质押时间:</span>
            <span className="font-medium">{stakedDays} 天</span>
          </div>
          <div className="flex justify-between text-sm">
            <span className="text-gray-600">剩余时间至零费用:</span>
            <span className="font-medium">{remainingDays} 天</span>
          </div>
        </div>
        
        {remainingTime > 0 ? (
          <>
            <p className="text-sm text-gray-600 mb-3">零费用提款倒计时:</p>
            <Countdown 
              date={Date.now() + remainingTime * 1000}
              renderer={renderer}
            />
          </>
        ) : (
          <span className="text-green-600 font-medium">费用已减至0%!</span>
        )}
        
        <div className="mt-4">
          <div className="w-full bg-gray-200 h-2 rounded-full overflow-hidden">
            <div 
              className="bg-gradient-to-r from-bluebrand-400 to-primary-500 h-full rounded-full transition-all duration-500"
              style={{ width: `${progress}%` }}
            />
          </div>
          <div className="flex justify-between text-xs text-gray-600 mt-1">
            <span>已质押: {stakedDays}天</span>
            <span>100天</span>
          </div>
        </div>
      </div>
    </GlassCard>
  );
};

export default FeeDecayCounter; 