import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { useWeb3 } from '../context/Web3Context';
import { ethers } from 'ethers';
import GlassCard from '../components/GlassCard';
import { formatAmount } from '../utils/contract';
import glassToast from '../utils/toastUtils';
import { 
  UserGroupIcon, 
  LinkIcon,
  ArrowTrendingUpIcon,
  DocumentDuplicateIcon,
  GiftIcon,
  ChartBarIcon
} from '@heroicons/react/24/outline';
import { CircularProgress } from '@mui/material';

const ReferralSystem = () => {
  const { account, contract, isConnected } = useWeb3();
  
  // 推荐链接
  const referralLink = account ? `${window.location.origin}?ref=${account}` : '';
  
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [referralData, setReferralData] = useState({
    totalReferrals: 0,
    currentReferralRate: 0,
    referralList: [],
    totalReferredStaked: 0,
    currentLevel: 1,
    nextLevel: null,
    nextRate: null,
    nextThreshold: null,
    progress: 0
  });
  const [referralDetails, setReferralDetails] = useState({});


  // 格式化地址显示
  const formatAddress = (address) => {
    if (!address || typeof address !== 'string') {
      return '-';
    }
    try {
      return `${address.substring(0, 6)}...${address.substring(address.length - 4)}`;
      } catch (error) {
      console.error('格式化地址失败:', error, '原始值:', address);
      return '-';
    }
  };

  // 格式化日期函数
  const formatDate = (timestamp) => {
    if (!timestamp || timestamp === '0') return '未质押';
    try {
      const date = new Date(Number(timestamp) * 1000);
      if (isNaN(date.getTime())) return '无效日期';
      return date.toLocaleString('zh-CN', {
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit'
      });
    } catch (error) {
      console.error('日期格式化错误:', error);
      return '日期错误';
    }
  };

  // 复制推荐链接
  const copyReferralLink = async () => {
    try {
      await navigator.clipboard.writeText(referralLink);
      glassToast.success('推荐链接已复制到剪贴板');
    } catch (e) {
      glassToast.error('复制失败，请手动复制');
    }
  };

  // 加载推荐数据
  const loadReferralData = useCallback(async () => {
    if (!account || !contract) {
      console.log('账户或合约未连接:', { account, contract });
      return;
    }

    try {
      setLoading(true);
      setError(null);

      console.log('开始加载推荐数据...');

      // 获取用户推荐信息
      const userInfo = await contract.getUserInfo(account);
      console.log('用户信息:', userInfo);

      const [userTotalStaked, referrer, totalReferred, currentStakingRate, currentReferralRate] = userInfo;

      // 获取推荐列表
      const referrals = await contract.getReferralList(account);
      console.log('推荐列表:', referrals);

      // 获取推荐费率配置
      const [stakingRates, referralRatesConfig] = await contract.getAllRateConfigs();
      console.log('费率配置:', { stakingRates, referralRatesConfig });

      const rates = referralRatesConfig.map(rate => ({
        level: Number(rate.level),
        rate: Number(rate.rate) / 10000,
        threshold: Number(rate.threshold)
      }));

      // 计算当前等级和下一等级
      const totalReferredAmount = Number(totalReferred) || 0;

      let currentLevel = 1;
      let nextLevel = null;
      let nextRate = null;
      let nextThreshold = null;
      let currentRate = Number(currentReferralRate) / 10000 || 0;

      for (let i = 0; i < rates.length; i++) {
        if (totalReferredAmount >= rates[i].threshold) {
          currentLevel = rates[i].level;
          currentRate = rates[i].rate;
        } else {
          nextLevel = rates[i].level;
          nextRate = rates[i].rate;
          nextThreshold = rates[i].threshold;
          break;
        }
      }

      // 计算进度
      const progress = nextThreshold ? (totalReferredAmount / nextThreshold) * 100 : 100;

      // 更新状态
      setReferralData({
        totalReferrals: referrals.length || 0,
        currentReferralRate: currentRate,
        referralList: referrals || [],
        totalReferredStaked: totalReferredAmount,
        currentLevel,
        nextLevel,
        nextRate,
        nextThreshold,
        progress
      });

      console.log('推荐数据更新完成:', {
        totalReferrals: referrals.length || 0,
        totalReferredStaked: totalReferredAmount,
        currentRate,
        currentLevel,
        nextLevel
      });

      // 获取每个推荐地址的详细信息
      const details = {};

      for (const address of referrals) {
        if (!address) continue;

        try {
          const userInfo = await contract.getUserInfo(address);
          const [addressTotalStaked, , , , ] = userInfo;
          
          // 获取用户的质押记录
          let timestamp = '0';
          try {
            const activeStakeIndices = await contract.getActiveStakeIndices(address);
            if (activeStakeIndices && activeStakeIndices.length > 0) {
              const latestStakeIndex = activeStakeIndices[activeStakeIndices.length - 1];
              const stakeDetails = await contract.getStakeDetails(address, latestStakeIndex);
              timestamp = stakeDetails.startTime.toString();
            }
          } catch (stakeError) {
            console.error(`获取地址 ${address} 质押时间失败:`, stakeError);
          }
          
          details[address.toLowerCase()] = {
            totalStaked: addressTotalStaked?.toString() || '0',
            timestamp: timestamp
          };
        } catch (error) {
          console.error(`获取地址 ${address} 信息失败:`, error);
          details[address.toLowerCase()] = {
            totalStaked: '0',
            timestamp: '0'
          };
        }
      }

      setReferralDetails(details);
      console.log('推荐详情更新完成:', details);

    } catch (error) {
      console.error('加载推荐数据失败:', error);
      setError(error.message || '加载推荐数据失败，请重试');
      glassToast.error(error.message || '加载推荐数据失败，请重试');
    } finally {
      setLoading(false);
    }
  }, [account, contract]);
    
  // 加载推荐数据
  useEffect(() => {
    if (isConnected && account && contract) {
      console.log('开始加载推荐数据:', { account, contract });
      loadReferralData();
    }
  }, [isConnected, account, contract, loadReferralData]);

  // 准备表格数据
  const tableData = useMemo(() => {
    return referralData.referralList.map(address => {
      const details = referralDetails[address.toLowerCase()] || {
        totalStaked: '0',
        timestamp: '0'
      };
      return {
        key: `referral-${address.toLowerCase()}`,
        address,
        totalStaked: details.totalStaked,
        timestamp: details.timestamp
      };
    });
  }, [referralData.referralList, referralDetails]);

  // 未连接钱包
  if (!isConnected) {
    return (
      <div className="min-h-[70vh] flex flex-col items-center justify-center">
        <GlassCard className="max-w-md w-full text-center p-8">
          <h2 className="text-2xl font-bold text-primary-700 mb-4">推荐系统</h2>
          <p className="text-gray-600 mb-6">连接您的钱包以查看您的质押和收益数据</p>
          <p className="text-sm text-gray-600 mt-4">质押代币并邀请朋友可以获得更多收益</p>
        </GlassCard>
      </div>
    );
  }

  // 加载中
  if (loading) {
    return (
      <div className="min-h-[70vh] flex flex-col items-center justify-center">
        <div className="text-center">
          <CircularProgress className="text-primary-600" />
          <p className="mt-4 text-gray-600">加载中...</p>
        </div>
      </div>
    );
  }

  // 错误状态
  if (error) {
  return (
      <div className="min-h-[70vh] flex flex-col items-center justify-center">
        <GlassCard className="max-w-md w-full text-center p-8">
          <h2 className="text-2xl font-bold text-red-600 mb-4">加载失败</h2>
          <p className="text-gray-600">{error}</p>
        <button 
          onClick={() => window.location.reload()} 
            className="mt-4 glass px-4 py-2 text-primary-600 hover:bg-white/40"
        >
            重试
        </button>
        </GlassCard>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        <GlassCard 
          title="推荐统计" 
          icon={<ChartBarIcon className="h-5 w-5 text-primary-600" />}
        >
          <div className="mt-3 space-y-4">
            <div className="flex justify-between items-center">
              <span className="text-sm text-gray-600">总推荐人数</span>
              <span className="text-2xl font-semibold text-accent-600">
                {referralData.totalReferrals || 0}
              </span>
            </div>
            <div className="flex justify-between items-center">
              <span className="text-sm text-gray-600">总推荐质押量</span>
              <span className="text-2xl font-semibold text-primary-700">
                {formatAmount(referralData.totalReferredStaked || 0)} AOT
              </span>
            </div>
            <div className="flex justify-between items-center">
              <span className="text-sm text-gray-600">当前推荐费率</span>
              <span className="text-2xl font-semibold text-bluebrand-600">
                {(referralData.currentReferralRate || 0).toFixed(2)}%
              </span>
            </div>
          </div>
        </GlassCard>

        <GlassCard 
          title="推荐链接" 
          icon={<LinkIcon className="h-5 w-5 text-primary-600" />}
        >
          <div className="mt-3">
            <div className="flex items-center space-x-2 mb-3">
              <input
                type="text"
                value={referralLink}
                readOnly
                className="flex-1 bg-white/10 border border-white/20 rounded-lg px-3 py-2 text-sm text-gray-700 focus:outline-none focus:ring-2 focus:ring-primary-400"
              />
              <button
                onClick={copyReferralLink}
                className="px-3 py-2 btn btn-gold"
              >
                <DocumentDuplicateIcon className="h-4 w-4" />
                <span className="text-sm">复制</span>
              </button>
            </div>
            <p className="text-sm text-gray-600">
              分享此链接给朋友，获得推荐奖励
            </p>
          </div>
        </GlassCard>
        
        <GlassCard 
          title="推荐等级进度" 
          icon={<ArrowTrendingUpIcon className="h-5 w-5 text-bluebrand-600" />}
        >
          <div className="mt-3">
            {referralData.nextRate !== null ? (
              <>
                <div className="flex justify-between text-sm text-gray-600 mb-2">
                  <span>当前: {formatAmount(referralData.totalReferredStaked || 0)} AOT</span>
                  <span>目标: {formatAmount(referralData.nextThreshold || 0)} AOT</span>
              </div>
                <div className="w-full bg-gray-200 rounded-full h-2 mb-3">
                  <div 
                    className="bg-gradient-to-r from-bluebrand-400 to-primary-500 h-2 rounded-full transition-all duration-500" 
                    style={{ 
                      width: `${Math.min(referralData.progress || 0, 100)}%`
                    }}
                  ></div>
              </div>
                <p className="text-sm text-gray-600">
                  距离下一等级还需 <span className="font-semibold text-bluebrand-600">
                    {formatAmount(Math.max(0, (referralData.nextThreshold || 0) - (referralData.totalReferredStaked || 0)))}
                  </span> AOT
                </p>
                <p className="text-xs text-gray-500 mt-1">
                  升级后费率将提升至 {(referralData.nextRate || 0).toFixed(2)}%
              </p>
            </>
          ) : (
              <>
                <div className="text-center py-4">
                  <GiftIcon className="h-8 w-8 mx-auto text-green-500 mb-2" />
                  <p className="text-lg font-semibold text-green-600">恭喜！</p>
                  <p className="text-sm text-gray-600">您已达到最高推荐等级</p>
                </div>
              </>
            )}
          </div>
        </GlassCard>
      </div>
      
      {/* 推荐列表 */}
      <GlassCard 
        title="推荐列表" 
        icon={<UserGroupIcon className="h-5 w-5 text-primary-600" />}
      >
        <div className="mt-3">
          {referralData.referralList && referralData.referralList.length > 0 ? (
            <div className="space-y-4">
              {tableData.map((item, index) => (
                <div key={item.key} className="glass p-4 rounded-lg border border-white/20 hover:border-primary-400 transition-colors">
                  <div className="flex justify-between items-center">
                    <div className="flex items-center space-x-3">
                      <div className="w-8 h-8 bg-primary-500 rounded-full flex items-center justify-center text-white text-sm font-semibold">
                        {index + 1}
                      </div>
                      <div>
                        <p className="font-medium text-gray-700">{formatAddress(item.address)}</p>
                        <p className="text-sm text-gray-500">质押时间: {formatDate(item.timestamp)}</p>
                      </div>
                    </div>
                    <div className="text-right">
                      <p className="font-semibold text-primary-600">{formatAmount(item.totalStaked)} AOT</p>
                      <p className="text-sm text-gray-500">质押量</p>
                    </div>
                  </div>
                </div>
              ))}
          </div>
          ) : (
            <div className="text-center py-12">
              <UserGroupIcon className="h-16 w-16 mx-auto text-gray-300 mb-4" />
              <p className="text-gray-600 mb-2">暂无推荐用户</p>
              <p className="text-sm text-gray-500">分享您的推荐链接，邀请朋友加入</p>
          </div>
        )}
        </div>
      </GlassCard>
    </div>
  );
};

export default ReferralSystem; 