import React, { useState, useEffect } from 'react';
import { useWeb3 } from '../context/Web3Context';
import GlassCard from '../components/GlassCard';
import { formatAmount } from '../utils/contract';
import { 
  GiftIcon,
  ClockIcon,
  CheckCircleIcon,
  UserIcon,
  CurrencyDollarIcon,
  ChartBarIcon
} from '@heroicons/react/24/outline';
import { Button, CircularProgress } from '@mui/material';
import glassToast from '../utils/toastUtils';

const RewardsCenter = () => {
  const { account, contract, isConnected } = useWeb3();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [pendingRewards, setPendingRewards] = useState('0');
  const [rewardHistory, setRewardHistory] = useState([]);
  
  useEffect(() => {
    const init = async () => {
      if (contract && account) {
        try {
          setLoading(true);
          setError(null);
          await loadRewardsData();
      } catch (error) {
        console.error('加载奖励数据失败:', error);
          setError(error.message);
      } finally {
          setLoading(false);
        }
      } else {
        setLoading(false);
        setError(null);
      }
    };
    init();
  }, [contract, account]);

  const loadRewardsData = async () => {
    if (!contract || !account) {
      console.log('合约或账户未初始化:', { contract, account });
      return;
    }
    
    try {
      console.log('开始加载奖励数据...');
      
      // 检查合约是否已部署
      const code = await contract.provider.getCode(contract.address);
      if (code === '0x') {
        throw new Error('合约未部署');
      }

      // 获取待领取奖励
      const rewards = await contract.getPendingRewards(account);
      setPendingRewards(formatAmount(rewards));

      // 获取奖励历史记录
      const history = await contract.getUserRewardHistory(account);
      setRewardHistory(history);
      
      console.log('待领取奖励:', formatAmount(rewards));
      console.log('奖励历史记录数量:', history.length);

      setError(null);
    } catch (error) {
      console.error('加载奖励数据失败:', error);
      setError(error.message);
      glassToast.error('加载奖励数据失败: ' + error.message);
      throw error;
    }
  };

  const handleClaimRewards = async () => {
    if (!contract) return;
    try {
      setLoading(true);
      const tx = await contract.claimAllRewards();
      await tx.wait();
      glassToast.success('奖励领取成功！');
      loadRewardsData();
    } catch (error) {
      console.error('领取奖励失败:', error);
      glassToast.error('领取奖励失败: ' + error.message);
    } finally {
      setLoading(false);
    }
  };

  // 格式化时间
  const formatTime = (timestamp) => {
    const date = new Date(Number(timestamp) * 1000);
    return date.toLocaleString('zh-CN', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      hour12: false
    });
  };

  // 格式化地址
  const formatAddress = (address) => {
    if (!address || address === '0x0000000000000000000000000000000000000000') return '系统';
    return `${address.slice(0, 6)}...${address.slice(-4)}`;
  };

  // 获取奖励类型描述
  const getRewardTypeDescription = (rewardType) => {
    switch (rewardType) {
      case 0: return '质押奖励';
      case 1: return '推荐奖励';
      case 2: return '其他奖励';
      default: return '未知类型';
    }
  };

  // 获取操作类型描述
  const getOperationTypeDescription = (operationType) => {
    switch (operationType) {
      case 0: return '领取';
      case 1: return '自动发放';
      case 2: return '其他';
      default: return '未知操作';
    }
  };

  if (!isConnected) {
    return (
      <div className="min-h-[70vh] flex flex-col items-center justify-center">
        <GlassCard className="max-w-md w-full text-center p-8">
          <h2 className="text-2xl font-bold text-primary-700 mb-4">奖励中心</h2>
          <p className="text-gray-600 mb-6">连接您的钱包以查看您的奖励数据</p>
          <p className="text-sm text-gray-600 mt-4">质押代币并邀请朋友可以获得更多奖励</p>
        </GlassCard>
      </div>
    );
  }

  if (loading) {
    return (
      <div className="min-h-[70vh] flex flex-col items-center justify-center">
        <div className="text-center">
          <CircularProgress className="text-primary-600" />
          <p className="mt-4 text-gray-600">加载中...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-[70vh] flex flex-col items-center justify-center">
        <GlassCard className="max-w-md w-full text-center p-8">
          <h2 className="text-2xl font-bold text-red-600 mb-4">加载失败</h2>
          <p className="text-gray-600">{error}</p>
          <button 
            onClick={() => window.location.reload()} 
            className="mt-4 glass px-4 py-2 text-primary-600 hover:bg-white/40"
          >
            重试
          </button>
        </GlassCard>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* 页面标题 */}
      <div className="text-center mb-8">
        <h1 className="text-3xl font-bold text-primary-700 mb-2 flex items-center justify-center gap-3">
          <GiftIcon className="h-8 w-8 text-primary-600" />
          奖励中心
        </h1>
        <p className="text-gray-600">管理您的质押奖励和推荐奖励</p>
      </div>
      
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* 待领取奖励卡片 */}
      <GlassCard 
        title="待领取奖励" 
          icon={<ClockIcon className="h-5 w-5 text-orange-500" />}
          className="border-2 border-orange-500/30 bg-orange-500/10"
        >
          <div className="mt-3">
            <p className="text-3xl font-semibold text-orange-500 mb-2">
              {parseFloat(pendingRewards).toLocaleString()} AOT
            </p>
            <p className="text-sm text-gray-600 mb-4">
              可以立即领取的奖励
            </p>
            {parseFloat(pendingRewards) > 0 && (
              <button
                onClick={handleClaimRewards}
                disabled={loading}
                className="w-full btn btn-gold"
              >
                {loading ? '领取中...' : '立即领取'}
              </button>
            )}
            {parseFloat(pendingRewards) === 0 && (
              <div className="text-center py-4">
                <p className="text-gray-500">暂无待领取奖励</p>
          </div>
            )}
        </div>
      </GlassCard>
      
        {/* 奖励统计卡片 */}
      <GlassCard 
          title="奖励统计" 
          icon={<ChartBarIcon className="h-5 w-5 text-blue-500" />}
        >
          <div className="mt-3">
            <div className="space-y-3">
              <div className="flex justify-between items-center">
                <span className="text-gray-600">总奖励记录</span>
                <span className="font-semibold text-primary-700">{rewardHistory.length} 笔</span>
              </div>
              
              <div className="flex justify-between items-center">
                <span className="text-gray-600">质押奖励</span>
                <span className="font-semibold text-green-600">
                  {rewardHistory.filter(r => r.rewardType === 0).length} 笔
                </span>
              </div>
              
              <div className="flex justify-between items-center">
                <span className="text-gray-600">推荐奖励</span>
                <span className="font-semibold text-blue-600">
                  {rewardHistory.filter(r => r.rewardType === 1).length} 笔
                </span>
              </div>
              
              <div className="flex justify-between items-center">
                <span className="text-gray-600">总奖励金额</span>
                <span className="font-semibold text-yellow-600">
                  {rewardHistory.reduce((sum, r) => sum + parseFloat(formatAmount(r.amount)), 0).toFixed(2)} AOT
                </span>
              </div>
          </div>
          </div>
      </GlassCard>
      </div>
      
      {/* 奖励领取记录列表卡片 */}
      <GlassCard 
        title="奖励历史记录" 
        icon={<CheckCircleIcon className="h-5 w-5 text-green-500" />}
      >
        <div className="mt-3">
          {rewardHistory.length > 0 ? (
            <div className="space-y-3 max-h-64 overflow-y-auto">
              {rewardHistory.slice().reverse().map((record, index) => (
                <div key={index} className="p-3 bg-white/5 rounded-lg border border-white/10">
                  <div className="flex items-center justify-between mb-2">
                    <div className="flex items-center gap-2">
                      <CheckCircleIcon className="h-4 w-4 text-green-500" />
                      <span className="font-semibold text-gray-800">
                        {parseFloat(formatAmount(record.amount)).toLocaleString()} AOT
                      </span>
                    </div>
                    <span className="text-sm text-green-400 font-medium">
                      {getOperationTypeDescription(record.operationType)}
                    </span>
                  </div>
                  <div className="grid grid-cols-2 gap-2 text-sm">
                    <div className="flex items-center gap-1">
                      <UserIcon className="h-3 w-3 text-gray-400" />
                      <span className="text-gray-400">来源:</span>
                      <span className="text-blue-400">{formatAddress(record.fromUser)}</span>
                    </div>
                    <div>
                      <span className="text-gray-400">类型:</span>
                      <span className="text-purple-400 ml-1">{getRewardTypeDescription(record.rewardType)}</span>
                    </div>
                  </div>
                  <div className="mt-2 text-xs text-gray-500">
                    {formatTime(record.timestamp)}
                  </div>
                </div>
              ))}
          </div>
        ) : (
          <div className="text-center py-8">
              <CheckCircleIcon className="h-12 w-12 text-gray-400 mx-auto mb-3" />
              <p className="text-gray-500">暂无奖励记录</p>
              <p className="text-xs text-gray-400 mt-2">开始质押或邀请朋友来获得奖励</p>
          </div>
        )}
        </div>
      </GlassCard>
    </div>
  );
};

export default RewardsCenter; 